INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('msbtr5b2kiokrb5o22xmsbtr5kxgpucz', '2026-Q3', 'Set/2026 (T3)', '2026-09-17T14:20'::timestamptz, 'Lejandre Karol Fortes Meneses', 'lejandre karol fortes meneses', 'PHARUS', 'Gabriel Oliveira', 6.0, 'Detrator', 9.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Entrei no plano em maio, estamos em setembro e Ainda não surgiram os empreendimentos prometidos  (leilões).', 'Mais transparência nos investimentos. Por exemplo solicitei dados reais dos últimos leilões e demorou meses para me informarem 3 imóveis com os dados. Planilha desenvolvida para simular o aumento patrimonial é irrealista. Ela leva em conta sincronismo perfeito entre investimentos. Na prática pode esperar meses. E tempo é fundamental.', NULL, 'Ver na prática os resultados dos investimentos e ter considerável desconto na taxa de renovação.', 'Já era uma pessoa financeiramente organizada. Então para mim o que mais vale é o plano de aumento patrimonial em prática. No entanto os leilões em série prometidos estão demorando muito.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'msbtr5b2kiokrb5o22xmsbtr5kxgpucz', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLU